CREATE TABLE IF NOT EXISTS v2_draw_order_{{suffix}}(order_id varchar(128) PRIMARY KEY,user_id varchar(64) NOT NULL,activity_id bigint NOT NULL,state varchar(32) NOT NULL,snapshot json NOT NULL,recovery_status varchar(32) NOT NULL DEFAULT 'ACTIVE',version bigint NOT NULL DEFAULT 0,last_progress_at datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),confirmed_at datetime(6),reserved_at datetime(6),delivered_at datetime(6),INDEX draw_recovery(recovery_status,state,last_progress_at,order_id),INDEX draw_user(user_id,activity_id),INDEX draw_backlog(state,last_progress_at,order_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS v2_award_record_{{suffix}}(order_id varchar(128) PRIMARY KEY,user_id varchar(64) NOT NULL,state varchar(32) NOT NULL,snapshot json NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS v2_award_delivery_{{suffix}}(order_id varchar(128) PRIMARY KEY,user_id varchar(64) NOT NULL,award_hash char(64) NOT NULL,snapshot json NOT NULL,delivered_at datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS v2_recovery_scan_cursor(aggregate_type varchar(32) NOT NULL,aggregate_id varchar(128) NOT NULL,checked_at datetime(6) NOT NULL,PRIMARY KEY(aggregate_type,aggregate_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS v2_raffle_stage(order_id varchar(128) NOT NULL,stage varchar(32) NOT NULL,recorded_at datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(order_id,stage)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
